import 'package:flutter/material.dart';
class HeatmapWidget extends StatelessWidget { const HeatmapWidget({super.key}); @override Widget build(BuildContext context) => SizedBox(height: 110, child: GridView.builder(padding: EdgeInsets.zero, physics: const NeverScrollableScrollPhysics(), gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 7, mainAxisSpacing: 4, crossAxisSpacing: 4), itemCount: 49, itemBuilder: (_, i) => Container(decoration: BoxDecoration(color: Colors.white.withOpacity((i % 5) / 10 + 0.08), borderRadius: BorderRadius.circular(4)) ))); }
